[assistant] Sure, I can help you with that! Here's a simple Node.js application using the `peer` library for video chat. This example uses Express for the server and Socket.IO for real-time communication. Make sure to install the required packages by running `npm install express socket.io peer`.

Here's the code for the application:

```javascript
const express = require('express');
const app = express();
const http = require('http').createServer(app);
const io = require('socket.io')(http);
const { ExpressPeerServer } = require('peer');

const peerServer = ExpressPeerServer(http, {
 debug: true,
});

app.use('/peerjs', peerServer);

app.get('/', (req, res) => {
  res.sendFile(__dirname + '/index.html');
});

io.on('connection', (socket) => {
 socket.on('join-room', (roomId, userId) => {
    socket.join(roomId);
    socket.to(roomId).broadcast.emit('user-connected', userId);

    socket.on('disconnect', () => {
      socket.to(roomId).broadcast.emit('user-disconnected', userId);
    });
  });
});

http.listen(3000, () => {
 console.log('Server is running on port 3000');
});
```

Create an `index.html` file in the same directory with the following content:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Video Chat</title>
  <script src="/socket.io/socket.io.js"></script>
  <script src="https://unpkg.com/peerjs@1.3.1/dist/peerjs.min.js"></script>
  <style>
    #video-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
      grid-gap: 1rem;
    }

    video {
      width: 100%;
      height: auto;
    }
  </style>
</head>
<body>
  <div id="video-grid"></div>

  <script>
    const socket = io('/');
    const videoGrid = document.getElementById('video-grid');

    const myPeer = new Peer();

    myPeer.on('open', (id) => {
      socket.emit('join-room', 'room-id', id);
    });

    socket.on('user-connected', (userId) => {
      connectToNewUser(userId, stream);
    });

    let stream;
    navigator.mediaDevices.getUserMedia({ video: true, audio: true })
      .then((currentStream) => {
        stream = currentStream;
        addVideoStream(videoGrid, stream);

        myPeer.on('call', (call) => {
          call.answer(stream);
          const video = document.createElement('video');
          call.on('stream', (userVideoStream) => {
            addVideoStream(videoGrid, userVideoStream);
          });
        });

        socket.on('user-disconnected', (userId) => {
          if (peers[userId]) {
            peers[userId].close();
          }
        });
      });

    const peers = {};

    function connectToNewUser(userId, stream) {
      const call = myPeer.call(userId, stream);
      const video = document.createElement('video');
      call.on('stream', (userVideoStream) => {
        addVideoStream(videoGrid, userVideoStream);
      });
      call.on('close', () => {
        video.remove();
      });

      peers[userId] = call;
    }

    function addVideoStream(videoGrid, stream) {
      const video = document.createElement('video');
      video.srcObject = stream;
      video.addEventListener('loadedmetadata', () => {
        video.play();
      });
      videoGrid.append(video);
    }
  </script>
</body>
</html>
```

Replace `'room-id'` with a unique room identifier for each chat session. This application allows multiple users to join a video chat room and communicate in real-time.
