        raise ValueError("Invalid SQL query. Missing SELECT clause.")

    fields = [field.strip() for field in select_match.group(1).split(',')]
    collection_name = select_match.group(2)

    if collection_name != collection.name:
        raise ValueError(f"SQL query refers to a different collection: {collection_name}")

    filter_query = {}
    if where_match:
        where_clause = where_match.group(1)
        filter_query = parse_where_clause(where_clause)

    sort_query = {}
    if order_by_match:
        order_by_clause = order_by_match.group(1)
        sort_query = parse_order_by_clause(order_by_clause)

    limit = None
    if limit_match:
        limit = int(limit_match.group(1))

    # Build MongoDB query
    mongo_query = {
        "$project": {field: 1 for field in fields},
        "$match": filter_query,
        "$sort": sort_query,
    }

    if limit:
        mongo_query["$limit"] = limit

    return mongo_query


def parse_where_clause(where_clause):
    # Complex WHERE clause parser, supports various operators
    conditions = re.split(r'\s+AND\s+', where_clause)
    filter_query = {}

    for condition in conditions:
        field, operator, value = re.split(r'\s*=\s*', condition, maxsplit=2)
        if operator.lower() == "like":
            filter_query[field] = {"$regex": value}
        elif operator.lower() == "between":
            min_value, max_value = value.split(',')
            filter_query[field] = {"$gte": min_value, "$lte": max_value}
        else:
            filter_query[field] = {"$eq": value}

    return filter_query


def parse_order_by_clause(order_by_clause):
    # Complex ORDER BY clause parser, supports various directions
    order_by_parts = re.split(r'\s*,\s*', order_by_clause)
    sort_query = {}

    for part in order_by_parts:
        field, direction = re.split(r'\s+', part)
        if direction.upper() == "DESC":
            sort_query[field] = -1
        else:
            sort_query[field] = 1

    return sort_query


# Example usage
client = MongoClient("mongodb://localhost:27017/")
db = client["test_database"]
collection = db["test_collection"]

sql_query = "SELECT field1, field2 FROM test_collection WHERE field1 LIKE 'value%' AND field2 BETWEEN 'value1' AND 'value2' ORDER BY field1 DESC, field2 ASC LIMIT 10"
mongo_query = sql_to_mongo_query(sql_query, collection)

print(mongo_query)
```

This updated code now supports the `LIKE` and `BETWEEN` operators in the `WHERE` clause and allows sorting by multiple fields in different directions. You can further extend this code to support more complex SQL queries and MongoDB features.

