```php
<?php

function generateCombinations($length) {
  $binary = "";
  for ($i = 0; $i < pow(2, $length); $i++) {
    $binary .= dechex($i);
    yield bin2hex($binary);
  }
}

$length = 8; // Example length
$combinations = generateCombinations($length);

echo "Combinations for length $length: \n";
foreach ($combinations as $combination) {
  echo $combination . "\n";
}
?>
```

