import numpy as np

class Probe:
    def __init__(self, galaxy, x, y):
        self.galaxy = galaxy
        self.x = x
        self.y = y
        self.resources = 100
        self.level = 1

    def explore(self):
        # Implement exploration logic
        pass

    def reproduce(self):
        # Implement reproduction logic
        if self.resources >= 50:
            self.resources -= 50
            self.galaxy.probes.append(Probe(self.galaxy, self.x, self.y))

    def collect_resources(self):
        # Implement resource collection logic
        self.resources += 10

    def upgrade(self):
        # Implement upgrade logic
        if self.resources >= 100:
            self.resources -= 100
            self.level += 1

class Galaxy:
    def __init__(self, width, height, num_stars):
        self.width = width
        self.height = height
        self.num_stars = num_stars
        self.stars = self.generate_stars()
        self.probes = []

    def generate_stars(self):
        stars = np.random.choice([0, 1], size=(self.width, self.height), p=[0.9, 0.1])
        return stars

    def update(self, explore_ratio, reproduce_ratio, collect_ratio, upgrade_ratio):
        total_probes = len(self.probes)
        if total_probes == 0:
            return

        probes_to_explore = int(total_probes * explore_ratio)
        probes_to_reproduce = int(total_probes * reproduce_ratio)
        probes_to_collect = int(total_probes * collect_ratio)
        probes_to_upgrade = int(total_probes * upgrade_ratio)

        probes = self.probes.copy()
        np.random.shuffle(probes)

        for probe in probes[:probes_to_explore]:
            probe.explore()

        for probe in probes[probes_to_explore:probes_to_explore + probes_to_reproduce]:
            probe.reproduce()

        for probe in probes[probes_to_explore + probes_to_reproduce:probes_to_explore + probes_to_reproduce + probes_to_collect]:
            probe.collect_resources()

        for probe in probes[probes_to_explore + probes_to_reproduce + probes_to_collect:]:
            probe.upgrade()
```

