        endTime: '00:02:30'
    },
    {
        speaker: 'Speaker 2',
        startTime: '00:02:30',
        endTime: '00:05:00'
    },
    // Add more speakers as needed
];

// Function to update the timeline based on the video's current time
function updateTimeline() {
    const currentTime = video.currentTime;
    const duration = video.duration;

    // Clear existing timeline parts
    timeline.innerHTML = '';

    // Calculate the percentage of the video that has been played
    const playedPercentage = (currentTime / duration) * 100;

    // Create a new timeline part for each speaker
    speakerTimelineData.forEach((speaker) => {
        const startTime = new Date(speaker.startTime).getTime();
        const endTime = new Date(speaker.endTime).getTime();

        // Calculate the width of the timeline part based on the speaker's speaking time
        const speakerWidth = ((endTime - startTime) / duration) * 100;

        // Create a new timeline part element
        const timelinePart = document.createElement('div');
        timelinePart.classList.add('timeline-part');
        timelinePart.style.width = `${speakerWidth}%`;

        // Add the timeline part to the timeline container
        timeline.appendChild(timelinePart);
    });
}

// Update the timeline when the video starts playing
