```python
from bokeh.plotting import figure, show
from bokeh.models import ColumnDataSource, CustomJS, Select, RadioButtonGroup, Div, HoverTool
from bokeh.layouts import column
import numpy as np

# Define the tools you want to use
TOOLS = "pan,wheel_zoom,box_zoom,reset,save"

# Define the tooltip
hover_tool = HoverTool(
    tooltips=[
        ( 'Date',   '@x{%F}'),
        ( 'Count',  '@y{int}' ),
    ],
    formatters={
        '@x': 'datetime', # use 'datetime' formatter for '@x' field
    },
    # display a tooltip whenever the cursor is vertically in line with a glyph
    #mode = 'vline'
)

# Create a new plot
f = figure(tools = TOOLS, 
    width = 800, 
    height = 400, 
    x_axis_label = 'Date',
    y_axis_label = 'Product/Environment/Service Rating'
)
f.tools.append(hover_tool)

# Create a ColumnDataSource containing the data to plot
source = ColumnDataSource(
    data = dict(
        x = df['review_time'], 
        y = df['产品'], # included for the tooltips
    )
)

# Create a ColumnDataSource containing all the necessary data so that you can send it to javascript for filtering
allSource = ColumnDataSource(
    data = dict(
        review_time = df['review_time'], 
        产品 = df['产品'],
        环境 = df['环境'],
        服务 = df['服务'],
    )
)

# Define the dropdown menu 
# (Note: Bokeh call's this select, because of the html nomenclature; there is also a difference Bokeh Dropdown)
select = Select(title = '', 
    value = '产品',
    options = ['产品', '环境', '服务'],
    width = 200,
    margin = (5, 5, 5, 80)
)

# Define some radio buttons
radio = RadioButtonGroup(
    labels = ['Product', 'Environment', 'Service'], 
    active = 0,
    width = 100,
    margin = (5, 5, 5, 80)
)

# Javascript code for the callback
callback = CustomJS(
    args = dict(
        source = source, 
        allSource = allSource,
        select = select,
        radio = radio,
        ranges = dict(
            x = f.x_range, 
            y = f.y_range
        ) 
    ),
    code = 
    """
        // get the value from the dropdown
        var key = select.value;

        //convert the value from the radio button to a key
        if (radio.active == 1) key = '环境';
        if (radio.active == 2) key = '服务';      

        // filter the full data set to include only those from that country
        if (key){
            var x = allSource.data.review_time;
            var y = allSource.data[key];

            //update the data in the plot
            source.data.x = x;
            source.data.y = y;
            source.change.emit();

            //reset the axis limits
            //note that this... syntax may not work on all browsers
            ranges.x.start = Math.min(...x); 
            ranges.x.end =  Math.max(...x);
            ranges.y.start = Math.max(Math.min(...y),0); 
            ranges.y.end =  Math.max(...y);
        }

    """
)

#attach the callback 
select.js_on_change('value', callback)
radio.js_on_click(callback)

show(column([
    Div(text = '<h1>Bokeh Product/Environment/Service Ratings Explorer</h1>'), 
    select,
    radio,
    f]
))
```

This code will create a Bokeh plot with a dropdown menu and radio buttons to filter the data and display the selected rating over time. The plot will update dynamically based on the user's selection.

