    while ($i < $length) {
        $char = $data[$i];
        $count = ord($data[$i + 1]);

        $result .= str_repeat($char, $count);
        $i += 2;
    }

    return $result;
}

$decompressedData = rleDecompress(file_get_contents('data.txt.rle'));

if ($decompressedData !== false) {
