```csharp
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class PipeManager : MonoBehaviour
{
    public int maxPipes = 5;
    public float pipeSpawnTime = 2f;
    public float pipeWidth = 50f;
    public float pipeHeight = 200f;
    public float gap = 100f;
    public float pipeSpeed = 2f;

    private List<GameObject> pipes = new List<GameObject>();
    private float spawnTime = 0f;

    void Start()
    {
        StartCoroutine(SpawnPipes());
    }

    IEnumerator SpawnPipes()
    {
        while (true)
        {
            spawnTime -= Time.deltaTime;
            if (spawnTime <= 0)
            {
                spawnTime = Random.Range(0, pipeSpawnTime);
                SpawnPipe();
            }
            yield return null;
        }
    }

    void SpawnPipe()
    {
        GameObject newPipe = Instantiate(pipePrefab, new Vector3(transform.position.x, transform.position.y, 0), Quaternion.identity);
        newPipe.transform.DOF = DOF.None;
        newPipe.transform.SetParent(transform);
        pipes.Add(newPipe);
    }

    void Update()
    {
        for (int i = 0; i < pipes.Count; i++)
        {
            GameObject pipe = pipes[i];
            pipe.transform.Translate(Vector3.right * -pipeSpeed * Time.deltaTime);

            if (pipe.transform.position.x <= -pipeWidth)
            {
                pipes.RemoveAt(i);
                Destroy(pipe);
            }
        }
    }

    public void OnCollisionEnter2D(Collision2D collision)
    {
        if (collision.gameObject.CompareTag("Pipe"))
        {
            Debug.Log("Game Over!");
            Destroy(gameObject);
        }
    }
}
```

