```csharp
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class Pipe : MonoBehaviour
{
    public float pipeWidth = 50f;
    public float pipeHeight = 200f;
    public float gap = 100f;

    void Start()
    {
        GeneratePipe();
    }

    void GeneratePipe()
    {
        GameObject topPipe = new GameObject("Top Pipe");
        GameObject bottomPipe = new GameObject("Bottom Pipe");

        topPipe.transform.position = transform.position;
        bottomPipe.transform.position = transform.position;

        topPipe.transform.localScale = new Vector3(pipeWidth, pipeHeight, 1f);
        bottomPipe.transform.localScale = new Vector3(pipeWidth, pipeHeight, 1f);

        topPipe.transform.localScale = new Vector3(pipeWidth, pipeHeight - gap, 1f);
        bottomPipe.transform.localScale = new Vector3(pipeWidth, pipeHeight - gap, 1f);

        topPipe.AddComponent<BoxCollider2D>();
        bottomPipe.AddComponent<BoxCollider2D>();

        topPipe.transform.DOF = DOF.None;
        bottomPipe.transform.DOF = DOF.None;

        topPipe.transform.SetParent(transform);
        bottomPipe.transform.SetParent(transform);

