std::vector<float> blurBorders(const std::vector<bool>& input, int width, int height) {
    std::vector<float> output(input.size());

    // Define the convolution kernel
    const std::vector<float> kernel = {1.0f / 5.0f, 1.0f / 5.0f, 1.0f / 5.0f, 1.0f / 5.0f, 1.0f / 5.0f};

    // Pad the input with two zeros on each side
    std::vector<bool> paddedInput(input.size() + 4, false);
    std::copy(input.begin(), input.end(), paddedInput.begin() + 2);

    // Perform the convolution row by row
    for (int y = 0; y < height; ++y) {
        for (int x = 0; x < width; ++x) {
            int index = y * width + x;
            float sum = 0.0f;

            // Apply the kernel to the current pixel and its neighbors
            for (int i = 0; i < 5; ++i) {
                int kernelIndex = index + i - 2;
                if (kernelIndex >= 0 && kernelIndex < paddedInput.size()) {
                    sum += kernel[i] * (paddedInput[kernelIndex] ? 1.0f : 0.0f);
                }
            }

            output[index] = sum;
        }
    }

    return output;
