**Question:** Write a Node.js script that uses the `https` module to fetch data from a public API and then processes the data to extract specific information. The API endpoint you should use is `https://api.github.com/users/{username}`, where `{username}` is a GitHub username provided as a command-line argument. The script should output the user's name, location, and the number of public repositories they have.

Here's a suggested structure for the solution:

1. Import the required modules: `https`, `process`, and `util`.
2. Define a function `getUserData(username)` that takes a GitHub username as an argument and returns a promise that resolves with the user's data.
   - Use the `https.get()` method to make a GET request to the GitHub API endpoint with the provided username.
   - Pipe the response to a `StringDecoder` to collect the entire response body as a string.
   - Parse the response body as JSON and extract the user's name, location, and number of public repositories.
   - Return a promise that resolves with an object containing the extracted data.
3. In the main part of the script, use `process.argv` to get the GitHub username from the command-line arguments.
4. Call the `getUserData()` function with the provided username and use `async/await` or `.then()` to handle the promise.
5. Output the extracted data to the console in a formatted way.

Here's a sample implementation to get you started:

```javascript
const https = require('https');
const process = require('process');
const util = require('util');

const getUserData = (username) => {
  return new Promise((resolve, reject) => {
    const url = `https://api.github.com/users/${username}`;

    https.get(url, (res) => {
      const { statusCode } = res;

      if (statusCode !== 200) {
        reject(new Error(`Request failed with status code ${statusCode}`));
        return;
      }

      const decoder = new util.StringDecoder('utf-8');
      let rawData = '';

      res.on('data', (chunk) => {
        rawData += decoder.write(chunk);
      });

      res.on('end', () => {
        try {
          const parsedData = JSON.parse(rawData);
          const { name, location, public_repos } = parsedData;
          resolve({ name, location, publicRepos: public_repos });
        } catch (e) {
          reject(e);
        }
      });
    }).on('error', (e) => {
      reject(e);
    });
  });
};

(async () => {
 const username = process.argv[2];

  if (!username) {
    console.error('Please provide a GitHub username as a command-line argument.');
    process.exit(1);
  }

 try {
    const userData = await getUserData(username);
    console.log(`Name: ${userData.name}`);
    console.log(`Location: ${userData.location}`);
    console.log(`Public repositories: ${userData.publicRepos}`);
  } catch (e) {
    console.error(`Error fetching user data: ${e.message}`);
    process.exit(1);
  }
})();
```

