    const s3Client = new S3Client({
      region: 'us-east-1',
      credentials: {
        accessKeyId: process.env.AWS_ACCESS_KEY_ID,
        secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
      },
    });

    const command = new PutObjectCommand({
      Bucket: bucket,
      Key: key,
      Body: file,
      ContentType: 'application/octet-stream',
    });

    try {
      const response = await s3Client.send(command);
      console.log('File uploaded successfully:', response);
    } catch (error) {
      console.error('Error uploading file to S3:', error);
    }
  }
}
```

3. Create a controller to handle the file upload request:

```typescript
import { Controller, Post, Body, UploadedFile, UseInterceptors } from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import { FileService } from './file.service';

@Controller('files')
export class FilesController {
  constructor(private readonly fileService: FileService) {}

  @Post('upload')
  @UseInterceptors(FileInterceptor('file'))
  async uploadFile(@UploadedFile() file: Express.Multer.File) {
    const bucket = process.env.AWS_S3_BUCKET;
    const key = `files/${Date.now()}-${file.originalname}`;

    await this.fileService.uploadFileToS3(file.buffer, bucket, key);

    return { message: 'File uploaded successfully' };
  }
}
```

4. In your `main.ts` file, add the following code to configure the AWS S3 client:

```typescript
import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';
import { S3Client } from '@aws-sdk/client-s3';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);

  const s3Client = new S3Client({
    region: 'us-east-1',
    credentials: {
      accessKeyId: process.env.AWS_ACCESS_KEY_ID,
      secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
    },
  });

  app.useGlobalInterceptors(new S3ClientInterceptor(s3Client));

  await app.listen(3000);
}

