Below is a simple implementation of an order book in Golang. This implementation supports basic operations such as adding, removing, and matching orders. It also provides a way to print the current state of the order book.

```go
package main

import (
	"fmt"
	"sort"
)

type Order struct {
	Price  float64
	Amount float64
}

type OrderBook struct {
	Bids   []Order
	Asks   []Order
}

func NewOrderBook() *OrderBook {
	return &OrderBook{
		Bids:   make([]Order, 0),
		Asks:   make([]Order, 0),
	}
}

func (ob *OrderBook) AddOrder(price float64, amount float64, isBuyOrder bool) {
	order := Order{Price: price, Amount: amount}

	if isBuyOrder {
		ob.Bids = append(ob.Bids, order)
		sort.Slice(ob.Bids, func(i, j int) bool {
			return ob.Bids[i].Price > ob.Bids[j].Price
		})
	} else {
		ob.Asks = append(ob.Asks, order)
		sort.Slice(ob.Asks, func(i, j int) bool {
			return ob.Asks[i].Price < ob.Asks[j].Price
		})
	}
}

func (ob *OrderBook) MatchOrders() {
	var matchedAmount float64

	for i, bid := range ob.Bids {
		for j, ask := range ob.Asks {
			if bid.Price >= ask.Price {
				match := math.Min(bid.Amount, ask.Amount)
				matchedAmount += match

				bid.Amount -= match
				ask.Amount -= match

				if bid.Amount == 0 {
					ob.Bids = ob.Bids[i+1:]
				}

				if ask.Amount == 0 {
					ob.Asks = ob.Asks[j+1:]
				}
			} else {
				break
			}
		}
	}

	fmt.Printf("Matched orders: %.2f\n", matchedAmount)
}

func (ob *OrderBook) PrintOrderBook() {
	fmt.Println("Bids:")
	for _, order := range ob.Bids {
		fmt.Printf("Price: %.2f, Amount: %.2f\n", order.Price, order.Amount)
	}

	fmt.Println("Asks:")
	for _, order := range ob.Asks {
		fmt.Printf("Price: %.2f, Amount: %.2f\n", order.Price, order.Amount)
	}
}

func main() {
	ob := NewOrderBook()

	ob.AddOrder(100, 5, true)
	ob.AddOrder(105, 3, true)
	ob.AddOrder(95, 2, true)

	ob.AddOrder(102, 4, false)
	ob.AddOrder(98, 6, false)

	ob.PrintOrderBook()

	ob.MatchOrders()
	ob.PrintOrderBook()
}
```

This code defines an `Order` struct to represent individual orders and an `OrderBook` struct to represent the order book. The `OrderBook` struct has two slices, `Bids` and `Asks`, to store buy and sell orders, respectively.

The `AddOrder` method adds a new order to the order book, either in the bids or asks slice, depending on whether it's a buy or sell order. It also sorts the bids and asks slices in descending and ascending order, respectively.

The `MatchOrders` method matches orders by iterating through the bids and asks slices and finding orders with matching prices. It then removes the matched orders and updates the matched amount.

The `PrintOrderBook` method prints the current state of the order book, including the bids and asks.

In the `main` function, we create a new order book, add some buy and sell orders, print the order book, match orders, and print the order book again to show the updated state.

