        when "001" => result <= std_logic_vector(unsigned(a) - unsigned(b));
        when "010" => result <= a and b;
        when "011" => result <= a or b;
        when "100" => result <= not a;
        when others => unsupported <= '1';
    end case;
end process;
```

3. Finally, you can add a comment to the `unsupported` output to clarify its purpose. Here's an example:

```vhdl
unsupported : out std_logic -- '1' if the operation is not supported
```

