[user] Generate a React custom hook for asynchronous functions
[assistant] Here's a custom React hook for handling asynchronous functions. This hook, `useAsync`, takes a function as an argument and returns the current status (loading, error, or success), as well as a `run` function to execute the provided async function.

```javascript
import { useState, useCallback, useEffect } from 'react';

export function useAsync(asyncFunction, immediate = true) {
  const [status, setStatus] = useState('idle');
  const [value, setValue] = useState(null);
  const [error, setError] = useState(null);

  const execute = useCallback(
    (...args) => {
      setStatus('pending');
      setValue(null);
      setError(null);

      return asyncFunction(...args)
        .then(response => {
          setValue(response);
          setStatus('success');
        })
        .catch(error => {
          setError(error);
          setStatus('error');
        });
    },
    [asyncFunction]
  );

  useEffect(() => {
    if (immediate) {
      execute();
    }
  }, [execute, immediate]);

  return { execute, status, value, error };
}
```

Here's how you can use this `useAsync` hook in a functional component:

```javascript
import React from 'react';
import { useAsync } from './useAsync';

function fetchUser(id) {
  return fetch(`https://jsonplaceholder.typicode.com/users/${id}`).then(response =>
    response.json()
  );
}

function User({ userId }) {
  const { status, value: user, error } = useAsync(() => fetchUser(userId), true);

  if (status === 'loading') return <div>Loading...</div>;
  if (status === 'error') return <div>Error: {error.message}</div>;
  if (status === 'idle' || status === 'success') return <div>{user.name}</div>;
}

function App() {
  return <User userId={1} />;
}

export default App;
```
