[assistant] Here's an updated version of the `useAsync` hook that uses the `useReducer` hook to manage the state. This approach allows for better separation of concerns and easier state updates.

```javascript
import { useReducer, useCallback, useEffect } from 'react';

const ACTIONS = {
  IDLE: 'idle',
  PENDING: 'pending',
  SUCCESS: 'success',
  ERROR: 'error',
};

const initialState = {
  status: ACTIONS.IDLE,
  value: null,
  error: null,
};

function reducer(state, action) {
  switch (action.type) {
    case ACTIONS.PENDING:
      return { status: ACTIONS.PENDING, value: null, error: null };
    case ACTIONS.SUCCESS:
      return { status: ACTIONS.SUCCESS, value: action.payload, error: null };
    case ACTIONS.ERROR:
      return { status: ACTIONS.ERROR, value: null, error: action.payload };
    default:
      return state;
  }
}

export function useAsync(asyncFunction, immediate = true) {
  const [state, dispatch] = useReducer(reducer, initialState);

  const execute = useCallback(
    (...args) => {
      dispatch({ type: ACTIONS.PENDING });
      return asyncFunction(...args)
        .then(response => {
          dispatch({ type: ACTIONS.SUCCESS, payload: response });
        })
        .catch(error => {
          dispatch({ type: ACTIONS.ERROR, payload: error });
        });
    },
    [asyncFunction]
  );

  useEffect(() => {
    if (immediate) {
      execute();
    }
  }, [execute, immediate]);

  return { execute, ...state };
}
```

The usage of the hook remains the same as in the previous example. The main difference is that now the state is managed using a reducer, which makes it easier to handle complex state updates in the future if needed.
