[assistant] To create a simple Drawing App with ReactJS, Three.JS, and Drei library, follow these steps:

1. Set up the project:

- Create a new React app using `create-react-app`:

  ```bash
 npx create-react-app drawing-app
 cd drawing-app
  ```

- Install required packages:

  ```bash
  yarn add three @react-three/fiber @react-three/drei
  ```

2. Create the components:

- `DrawingCanvas.js`:

  ```jsx
  import React, { useRef, useState } from 'react';
  import { Canvas, useThree, useFrame } from '@react-three/fiber';
  import { OrbitControls, Line, ShapeGeometry } from '@react-three/drei';

 const DrawingCanvas = () => {
    const [points, setPoints] = useState([]);
    const [shape, setShape] = useState(null);
    const ref = useRef();

    useFrame(() => {
      if (ref.current) {
        ref.current.geometry.vertices = points;
        ref.current.geometry.verticesNeedUpdate = true;
      }
    });

    const addPoint = (event) => {
      const { clientX, clientY } = event;
      const { width, height } = ref.current.parent.getBoundingClientRect();
      const x = (clientX / width) * 2 - 1;
      const y = -(clientY / height) * 2 + 1;
      setPoints((prevPoints) => [...prevPoints, [x, y]]);
    };

    const createShape = () => {
      const shapeGeometry = new ShapeGeometry(points);
      setShape(shapeGeometry);
    };

    return (
      <Canvas
        onClick={addPoint}
        onDoubleClick={createShape}
        camera={{ position: [0, 0, 5] }}
      >
        <OrbitControls />
        <Line ref={ref} points={points} />
        {shape && (
          <mesh geometry={shape}>
            <meshStandardMaterial color="lightblue" />
          </mesh>
        )}
      </Canvas>
    );
  };

  export default DrawingCanvas;
  ```

- `App.js`:

  ```jsx
  import React from 'react';
  import DrawingCanvas from './DrawingCanvas';

