```jsx
import React, { useRef, useState, useEffect } from 'react';
import { Canvas, useThree, useFrame } from '@react-three/fiber';
import { OrbitControls, Line, ShapeGeometry, useHelper } from '@react-three/drei';
import { BoxHelper } from 'three';

const DrawingCanvas = ({ onPointsUpdate }) => {
  const [points, setPoints] = useState([]);
  const [shape, setShape] = useState(null);
  const [currentShape, setCurrentShape] = useState(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const ref = useRef();
  const boxHelperRef = useRef();

  useFrame(() => {
    if (ref.current) {
      ref.current.geometry.vertices = points;
      ref.current.geometry.verticesNeedUpdate = true;
    }
  });

  useEffect(() => {
    onPointsUpdate(points);
  }, [points, onPointsUpdate]);

  const addPoint = (event, shapeType) => {
    const { clientX, clientY } = event;
    const { width, height } = ref.current.parent.getBoundingClientRect();
    const x = (clientX / width) * 2 - 1;
    const y = -(clientY / height) * 2 + 1;

    switch (shapeType) {
      case 'line':
        setPoints((prevPoints) => [...prevPoints, [x, y]]);
        break;
      case 'rectangle':
      case 'square':
        if (points.length === 0) {
          setPoints([[-1, -1], [1, -1], [1, 1], [-1, 1]]);
        }
        break;
      case 'triangle':
        if (points.length === 0) {
          setPoints([[-1, -1], [0, 1], [1, -1]]);
        }
        break;
      case 'curve':
        if (points.length === 0) {
          setPoints([[0, -1], [0, 1]]);
        }
        break;
      default:
        break;
    }
  };

  const createShape = () => {
    if (currentShape && points.length > 0) {
      const shapeGeometry = new ShapeGeometry(points);
      setShape(shapeGeometry);
    }
  };

  const startDrawing = (shapeType) => {
    setCurrentShape(shapeType);
    setIsDrawing(true);
  };

  const stopDrawing = () => {
    setIsDrawing(false);
    createShape();
  };

  const generateVertices = (shapeType) => {
    switch (shapeType) {
      case 'rectangle':
        return [[-1, -1], [1, -1], [1, 1], [-1, 1]];
      case 'square':
        return [[-1, -1], [1, -1], [1, 1], [-1, 1]];
      case 'triangle':
        return [[-1, -1], [0, 1], [1, -1]];
      case 'curve':
        return [[0, -1], [0, 1]];
      default:
        return [];
    }
  };

  return (
    <Canvas
      onMouseDown={(event) => startDrawing('line')}
      onMouseMove={(event) => isDrawing && addPoint(event, currentShape)}
      onMouseUp={stopDrawing}
      onDoubleClick={createShape}
      camera={{ position: [0, 0, 5] }}
    >
      <OrbitControls />
      <Line ref={ref} points={points} />
      {shape && (
        <mesh geometry={shape}>
          <meshStandardMaterial color="lightblue" />
        </mesh>
      )}
      {currentShape === 'rectangle' || currentShape === 'square' || currentShape === 'triangle' ? (
        <mesh>
          <boxGeometry args={[2, 2, 2]} />
          <meshStandardMaterial color="red" transparent opacity={0.2} />
          <BoxHelper ref={boxHelperRef} args={[0, 0, 0, 1]} />
          <useHelper args={[boxHelperRef.current, BoxHelper]} />
        </mesh>
      ) : null}
    </Canvas>
  );
};

export default DrawingCanvas;
```

