1. **Set up the project**: First, create a new Rust project using Cargo:

   ```bash
   cargo new rust_tts_app
   cd rust_tts_app
   ```

2. **Add dependencies**: Add the following dependencies to your `Cargo.toml` file:

   ```toml
   [dependencies]
   reqwest = { version = "0.11", features = ["json"] }
   serde = { version = "1.0", features = ["derive"] }
   serde_json = "1.0"
   clipboard = "0.5"
   ```

3. **Create the API client**: Create a new module `api.rs` to interact with the ElevenLabs.io API:

   ```rust
   // src/api.rs

   use reqwest::{Client, Response};
   use serde::{Deserialize, Serialize};

   const API_URL: &str = "https://api.elevenlabs.io/v1";

   #[derive(Serialize, Deserialize, Debug)]
   struct TTSRequest {
       text: String,
   }

   #[derive(Serialize, Deserialize, Debug)]
   struct TTSResponse {
       audio_url: String,
   }

   pub async fn text_to_speech(text: &str) -> Result<String, Box<dyn std::error::Error>> {
       let client = Client::new();
       let request = TTSRequest { text: text.to_string() };

       let response: Response = client
           .post(format!("{}/tts", API_URL))
           .json(&request)
           .send()
           .await?;

       let tts_response: TTSResponse = response.json().await?;

       Ok(tts_response.audio_url)
   }
   ```

4. **Create the main function**: In your `main.rs`, create the main function that reads the clipboard and sends the text to the API:

   ```rust
   // src/main.rs

   use clipboard::{ClipboardContext, ClipboardProvider};
   use std::io::{self, Write};

   mod api;

   #[tokio::main]
   async fn main() -> Result<(), Box<dyn std::error::Error>> {
       let clipboard = ClipboardContext::new()?;
       let text = clipboard.get_contents()?;

       if text.is_empty() {
           println!("Clipboard is empty. Please copy some text first.");
           return Ok(());
       }

       let audio_url = api::text_to_speech(&text).await?;

       println!("Audio URL: {}", audio_url);

       // Play the audio using an external player like `play` on Linux or `afplay` on macOS
       let output = if cfg!(target_os = "linux") {
           io::Command::new("play")
               .arg("-q")
