```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <cctype>

int main() {
    // Initialize the array with given data
    char Arr[15] = {'h', 'e', 'L', 'I', 'o', '*', '7', 'W', 'O', 'r', 'L', '#', 'd', '-', '5'};

    // Vector to store symbols
    std::vector<char> symArr;

    // Unordered map to count occurrences of each letter (case insensitive)
    std::unordered_map<char, int> letterCount;

    // Iterate through the array
    for (char ch : Arr) {
        if (!isalpha(ch)) {
            // If the character is not a letter, it's a symbol
            symArr.push_back(ch);
        } else {
            // Convert to lowercase for case insensitive counting
            char lowerCh = tolower(ch);
            letterCount[lowerCh]++;
        }
    }

    // Print symbols
    std::cout << "Symbols: ";
    for (char sym : symArr) {
        std::cout << sym << " ";
    }
    std::cout << std::endl;

    // Print letters that appear only once
    std::cout << "Letters appearing only once: ";
    for (char ch : Arr) {
        if (isalpha(ch)) {
            char lowerCh = tolower(ch);
            if (letterCount[lowerCh] == 1) {
                std::cout << ch << " ";
                // Mark the letter as printed to avoid duplicates
                letterCount[lowerCh] = 0;
            }
        }
    }
    std::cout << std::endl;

    return 0;
}
```

### Explanation:
