```javascript
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const { authenticateUser } = require('./auth');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// Object to store chat rooms and their respective clients
const chatRooms = {};

io.on('connection', (socket) => {
  console.log('New client connected');

  // Join a chat room
  socket.on('join room', (roomName) => {
    if (!chatRooms[roomName]) {
      chatRooms[roomName] = [];
    }

    chatRooms[roomName].push(socket);
    socket.join(roomName);

    // Send all previous messages in the room to the new client
    socket.emit('room messages', chatRooms[roomName].map(client => client.data('messages')));
  });

  // Leave a chat room
  socket.on('leave room', (roomName) => {
    if (chatRooms[roomName]) {
      chatRooms[roomName] = chatRooms[roomName].filter(client => client !== socket);
      socket.leave(roomName);
    }
  });

  // Send a chat message to all clients in the same room
  socket.on('chat message', (msg) => {
    const authenticatedUser = authenticateUser(socket.id);
    const roomName = socket.rooms[1]; // Get the room name from the socket's rooms array

    if (chatRooms[roomName]) {
      chatRooms[roomName].forEach(client => {
        client.emit('chat message', { user: authenticatedUser.username, message: msg });
      });
    }
  });

  // Store chat messages in the socket's data object
  socket.on('store message', (msg) => {
    const authenticatedUser = authenticateUser(socket.id);
    const roomName = socket.rooms[1];

    if (chatRooms[roomName]) {
      chatRooms[roomName].forEach(client => {
        client.data('messages').push({ user: authenticatedUser.username, message: msg });
      });
    }
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');

    // Remove the client from all chat rooms
    Object.keys(chatRooms).forEach(roomName => {
      const roomClients = chatRooms[roomName];
      const index = roomClients.indexOf(socket);

      if (index !== -1) {
        roomClients.splice(index, 1);
      }
    });
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
```

