const maxTokens = modelMaxTokens - countTokens(modifiedPrompt) - buffer - completionMinTokens;

const contextDocuments = contextsEnhancement.contextDocumentValue || '';
const chatContext = chatContextEnhancement.contextRelevantExperimentalTextData || '';

// Calculate the number of tokens used by each context
const contextDocumentsTokens = countTokens(contextDocuments);
const chatContextTokens = countTokens(chatContext);

// Initialize the dynamic programming table
const dp = new Array(maxTokens + 1).fill('').map(() => new Array(contextDocumentsTokens + 1).fill('').map(() => new Array(chatContextTokens + 1).fill(0)));

// Fill in the dynamic programming table
for (let i = 0; i <= maxTokens; i++) {
  for (let j = 0; j <= contextDocumentsTokens; j++) {
    for (let k = 0; k <= chatContextTokens; k++) {
      // Calculate the remaining tokens
      const remainingTokens = maxTokens - i;

      // Calculate the number of tokens used by the first half of the context documents
      const firstHalfTokens = Math.min(remainingTokens / 2, j);

      // Calculate the number of tokens used by the second half of the context documents
      const secondHalfTokens = j - firstHalfTokens;

      // Calculate the total number of tokens used by both halves of the context documents
      const totalDocumentsTokens = firstHalfTokens + secondHalfTokens;

      // Calculate the total number of tokens used by the chat context
      const totalChatTokens = k + totalDocumentsTokens;

      // Update the dynamic programming table with the maximum number of tokens used
      dp[i][j][k] = Math.max(dp[i][j][k], totalChatTokens);
    }
  }
}

// Construct the final prompt by backtracking through the dynamic programming table
let prompt = '';
let i = maxTokens;
let j = contextDocumentsTokens;
let k = chatContextTokens;
while (i > 0 && j > 0 && k > 0) {
  // Calculate the remaining tokens
  const remainingTokens = maxTokens - i;

  // Calculate the number of tokens used by the first half of the context documents
  const firstHalfTokens = Math.min(remainingTokens / 2, j);

  // Calculate the number of tokens used by the second half of the context documents
  const secondHalfTokens = j - firstHalfTokens;

  // Calculate the total number of tokens used by both halves of the context documents
  const totalDocumentsTokens = firstHalfTokens + secondHalfTokens;

  // Calculate the total number of tokens used by the chat context
  const totalChatTokens = k + totalDocumentsTokens;

  // Check if the current combination of context documents and chat context maximizes the number of tokens used
  if (dp[i][j][k] === totalChatTokens) {
    // Add the first half of the context documents to the prompt
    prompt = `${contextDocuments.slice(0, firstHalfTokens * 2)}\n---\n\n${prompt}`;

    // Add the chat context to the prompt
    prompt = `${chatContext.slice(0, k)}\n<context block ends>\n\n${prompt}`;

    // Update the remaining tokens
    i -= totalChatTokens;
    j -= firstHalfTokens;
    k = 0;
  } else {
    // Move to the next combination of context documents and chat context
    k--;
  }
}

// Add the remaining context documents to the prompt
prompt = `${contextDocuments.slice(j * 2)}\n---\n\n${prompt}`;

// Add the modified prompt to the beginning of the final prompt
prompt = `${prompt}\n${modifiedPrompt}`;
